# -*- coding: utf-8 -*-
"""
Emit .expected.json sidecars for the pre-existing PDFs in
tests/fixtures/ (root + image_pdf/) that don't already have one.

Source of truth: coverage_inventory.json (run coverage_inventory.py first).
The 12 realworld/ fixtures already ship with sidecars from phase-2 — we
do NOT touch those. The 6 PDF/A fixtures already have sidecars too.

origin field is "pre-existing" — we cannot reliably trace exact provenance
from git for every file (some predate the current generator scripts).
"""
from __future__ import annotations

import json
import sys
from pathlib import Path


THIS_DIR = Path(__file__).resolve().parent


def main() -> int:
    inv_path = THIS_DIR / "coverage_inventory.json"
    if not inv_path.exists():
        print(f"ERROR: {inv_path} missing — run coverage_inventory.py first.",
              file=sys.stderr)
        return 2

    with open(inv_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    written = 0
    skipped = 0
    for rec in data["fixtures"]:
        rel = rec.get("relPath", "")
        if not rel:
            continue
        # Phase-3 generator already wrote its own sidecars
        if "phase3_" in rel:
            continue
        # PDF-79 (phase-61): this used to `continue` on realworld/ wholesale,
        # with the comment "already has sidecars". That was true of the twelve
        # fixtures the claim was written about — realworld/cid_mixed/,
        # realworld/corrupt_xref/, and the ten other SUBDIRECTORY fixtures —
        # and false of the seventeen PDFs sitting at the top of realworld/
        # (arxiv_*, irs_*, ssa_sf86, uscis_i9), which arrived later.
        #
        # The exclusion was keyed on a DIRECTORY; the fact it encoded was
        # about a LIST OF FILES. So seventeen tracked fixtures have had no
        # sidecar since they landed, and nothing noticed, because nothing ran
        # validate_sidecars.py — which is exactly the gap PDF-79 filed and
        # test_extraction_sidecar_conformance.cpp now closes.
        #
        # No special case is needed: the `sidecar.exists()` check below
        # already skips anything that has one, which is what the old comment
        # was reaching for.

        pdf_path = THIS_DIR / rel.replace("/", "\\") if "\\" not in rel else THIS_DIR / rel
        # Use forward-slash variant uniformly
        pdf_path = THIS_DIR / rel
        sidecar = pdf_path.with_suffix(".expected.json")
        if sidecar.exists():
            skipped += 1
            continue

        scripts = rec.get("scripts") or []
        category_tags = []
        if rec.get("isEncrypted"):
            category_tags.append("encrypted")
        else:
            category_tags.append("no-encryption")
        if rec.get("hasForm"):
            category_tags.append("has-form")
        if rec.get("hasAnnotations"):
            category_tags.append("has-annotations")
        if rec.get("hasImages"):
            category_tags.append("has-images")
        if rec.get("isLinearized"):
            category_tags.append("linearized")
        if rec.get("hasXrefStreams"):
            category_tags.append("xref-streams")
        if rec.get("hasOutputIntent"):
            category_tags.append("output-intent")
        if rec.get("hasStructTree"):
            category_tags.append("tagged")
        if rec.get("pdfaClaim"):
            category_tags.append(rec["pdfaClaim"].lower())

        sidecar_doc = {
            "pageCount": rec.get("pageCount"),
            "isEncrypted": rec.get("isEncrypted", False),
            "hasForm": rec.get("hasForm", False),
            "hasForms": rec.get("hasForm", False),
            "hasAnnotations": rec.get("hasAnnotations", False),
            "hasImages": rec.get("hasImages", False),
            "pdfVersion": rec.get("pdfVersion"),
            "fileSize": rec.get("fileSize"),
            "origin": "pre-existing",
            "category_tags": category_tags,
            "scripts": scripts,
            "contentKind": rec.get("contentKind"),
            "description": (
                "Pre-existing fixture; sidecar auto-generated by "
                "generate_existing_sidecars.py from coverage_inventory.json. "
                "Origin not back-traced — `origin: pre-existing`."
            ),
        }
        # PDF-79 (phase-61): TWO INCOMPATIBLE SIDECAR SCHEMAS COEXIST in this
        # tree, and giving the realworld/ fixtures sidecars at all is what
        # revealed it.
        #
        #   * this generator writes camelCase (`pageCount`), which is what
        #     validate_sidecars.py and the extraction suites read;
        #   * tests/test_realworld_corpus.cpp reads snake_case — `page_count`,
        #     `has_xref_repair`, `fixture_type` (see its obj.value() calls at
        #     lines 102-105) — because the twelve hand-written realworld/
        #     subdirectory sidecars use that spelling.
        #
        # Nothing caught the divergence because the two sets never overlapped:
        # the seventeen top-level realworld PDFs had NO sidecar, so
        # RealworldCorpusTest's parameterised cases did not exist for them.
        # Generating those seventeen INSTANTIATED seventeen new cases, every
        # one of which read `page_count`, got the -1 default, and failed.
        # A gap that hid a second gap.
        #
        # The aliases are emitted from the SAME source value rather than
        # written twice, so the two spellings cannot drift apart — the
        # `hasForm` / `hasForms` pair above is the same pattern, already
        # established in this file. Unifying the two schemas outright would
        # mean rewriting the twelve hand-authored sidecars and the test that
        # reads them, which is larger than PDF-79 scopes; it is recorded in
        # the phase-61 disposition rather than done quietly here.
        sidecar_doc["page_count"] = sidecar_doc["pageCount"]
        sidecar_doc["has_xref_repair"] = False
        sidecar_doc["fixture_type"] = rec.get("contentKind") or "pre-existing"

        with open(sidecar, "w", encoding="utf-8") as f:
            json.dump(sidecar_doc, f, indent=2, ensure_ascii=False)
            f.write("\n")
        written += 1

    print(f"Wrote {written} new sidecars; skipped {skipped} that already existed.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
